def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1]

    for i in range(n - 1):
        if s[i] > s[i + 1]:
            print("YES")
            print(i + 1, i + 2)
            return

    for i in range(n - 1):
        for j in range(i + 2, n + 1):
            if s[:i] + s[i:j][::-1] + s[j:] < s:
                print("YES")
                print(i + 1, j)
                return

    print("NO")

